    {
        var_visibleProcessando: false,
        var_visible: "Registros",
        var_textoSugestao: "Sugestão: Após análise, verificamos que o conteúdo informado não caracteriza Ocorrência Não Aeronáutica. De acordo com os critérios do procedimento vigente.",
        var_acao: Blank(),
        var_novaVersao: false
    }
);
Set(
    varColunaOrdenacao,
    "ID"
);
Set(
    varDirecaoOrdenacao,
    SortOrder.Descending
)

With(
    {
        _itens: SortByColumns(
            GalleryOcoNaero.AllItems,
            "data_inicio",
            SortOrder.Descending
        ),
        _periodo: If(
            IsBlank(ocoNaero_data_inicio.SelectedDate),
            "PERÍODO COMPLETO",
            Text(
                DateAdd(
                    ocoNaero_data_inicio.SelectedDate,
                    TimeZoneOffset(ocoNaero_data_inicio.SelectedDate),
                    TimeUnit.Minutes
                ),
                "[$-pt-BR]dd/mm/yyyy"
            ) & " A " & If(
                IsBlank(ocoNaero_data_fim.SelectedDate),
                "...",
                Text(
                    DateAdd(
                        ocoNaero_data_fim.SelectedDate,
                        TimeZoneOffset(ocoNaero_data_fim.SelectedDate),
                        TimeUnit.Minutes
                    ),
                    "[$-pt-BR]dd/mm/yyyy"
                )
            )
        ),
        _aeroporto: Upper(ocoNaero_aeroporto.Selected.Value),
        _totalRegistros: CountRows(GalleryOcoNaero.AllItems)
    },
    "<style>
