        flex: 1;
        background: #FFFFFF;
        border: 1px solid #E2E8F0;
        padding: 10px 16px;
        text-align: center;
    }
    .kpi-value {
        font-size: 22px; font-weight: 800; color: #0F172A;
        line-height: 1;
    }
    .kpi-label {
        font-size: 8px; color: #64748B; font-weight: 600;
        letter-spacing: 0.8px; margin-top: 4px;
