    tbody td {
        padding: 7px 10px;
        vertical-align: top;
        line-height: 1.35;
        font-size: 9px;
        color: #1E293B;
        border-top: 1px solid #F1F5F9;
        border-right: 1px solid #F1F5F9;
        word-break: break-word;
    }
    tbody td:last-child { border-right: none; }
    tbody tr:nth-child(even) td { background: #F8FAFC; }
