    .col-aero      { width: 90px; }
    .col-data      { width: 75px; }
    .col-tipo      { width: 140px; }
    .col-ocor      { width: 130px; }
    .col-descricao { width: 400px; }
    .col-acoes     { width: 360px; }
</style>
<!-- ============ CABEÇALHO ============ -->
<div class='header-bar'>
    <div class='header-brand'>
        <div>
            <div class='brand-name'>MOTIVA</div>
            <div class='brand-sub'>GESTÃO AEROPORTUÁRIA</div>
        </div>
    </div>
    <div class='header-title'>
        <h1>RELATÓRIO DE OCORRÊNCIAS NÃO AERONÁUTICAS</h1>
        <h2>" & _aeroporto & "</h2>
    </div>
    <div class='header-meta'>
        <div><strong>EMISSÃO:</strong> " & Text(
        Now(),
        "[$-pt-BR]dd/mm/yyyy HH:mm"
    ) & "</div>
        <div><strong>PERÍODO:</strong> " & _periodo & "</div>
    </div>
</div>
<!-- ============ FAIXA DE TIPOS ============ -->
<div class='types-strip'>
    <div class='types-label'>CLASSIFICAÇÕES CONTEMPLADAS</div>
    <div class='types-list'>
        INCÊNDIO EM VEGETAÇÃO &nbsp;•&nbsp; OUTRAS EMERGÊNCIAS &nbsp;•&nbsp; EMERGÊNCIA MÉDICA &nbsp;•&nbsp; APOIO PARA REMOÇÃO DE AERONAVE INOPERANTE &nbsp;•&nbsp; CAPTURA OU REMOÇÃO DE ANIMAIS OU INSETOS &nbsp;•&nbsp; EMERGÊNCIA COM MATERIAIS PERIGOSOS &nbsp;•&nbsp; EMERGÊNCIA EM INSTALAÇÕES OU EDIFICAÇÕES &nbsp;•&nbsp; EMERGÊNCIA POR DESASTRES NATURAIS
    </div>
</div>
<!-- ============ KPIs ============ -->
<div class='kpi-row'>
    <div class='kpi-card'>
        <div class='kpi-value kpi-accent'>" & Text(_totalRegistros) & "</div>
        <div class='kpi-label'>TOTAL DE OCORRÊNCIAS</div>
    </div>
    <div class='kpi-card'>
        <div class='kpi-value'>" & _aeroporto & "</div>
        <div class='kpi-label'>AEROPORTO</div>
    </div>
    <div class='kpi-card'>
        <div class='kpi-value'>" & _periodo & "</div>
        <div class='kpi-label'>PERÍODO ANALISADO</div>
    </div>
</div>
<!-- ============ TABELA ============ -->
<div class='table-wrapper'>
    <table>
        <thead>
            <tr>
                <th class='col-aero'>AEROPORTO</th>
                <th class='col-data'>DATA</th>
                <th class='col-tipo'>TIPO DE OCORRÊNCIA</th>
                <th class='col-ocor'>LOCAL</th>
                <th class='col-descricao'>DESCRIÇÃO DA OCORRÊNCIA</th>
                <th class='col-acoes'>AÇÕES EXECUTADAS</th>
            </tr>
        </thead>
        <tbody>" & Concat(
        _itens As R,
        "<tr>
        <td class='col-aero'>" & Upper(
            Coalesce(
                R.aeroporto,
                "-"
            )
        ) & "</td>
        <td class='col-data'>" & If(
            IsBlank(R.data_inicio),
            "-",
            Text(
                DateAdd(
                    R.data_inicio,
                    TimeZoneOffset(R.data_inicio),
                    TimeUnit.Minutes
                ),
                "[$-pt-BR]dd/mm/yyyy"
            )
        ) & "</td>
        <td class='col-tipo'>" & Upper(
            Coalesce(
                R.tipo_ocorrencia,
                "-"
            )
        ) & "</td>
        <td class='col-ocor'>" & Upper(
            Coalesce(
                Text(R.local_ocorrencia),
                "-"
            )
        ) & "</td>
        <td class='col-descricao'>" & Upper(
            Substitute(
                Coalesce(
                    If(
                        Not IsBlankOrError(R.descricao_sede) And R.descricao_sede <> "",
                        R.descricao_sede,
                        Not IsBlankOrError(R.descricao_aeroporto) And R.descricao_aeroporto <> "",
                        R.descricao_aeroporto,
                        R.descricao_ocorrencia
                    ),
                    "-"
                ),
                Char(10),
                "<br/>"
            )
        ) & "</td>
        <td class='col-acoes'>" & Upper(
            Substitute(
                Coalesce(
                    R.acao_executada,
                    "-"
                ),
                Char(10),
                "<br/>"
            )
        ) & "</td>
    </tr>"
    ) & "       </tbody>
    </table>
</div>
<!-- ============ RODAPÉ ============ -->
<div class='report-footer'>
    <div><span class='footer-brand'>MOTIVA</span> &nbsp;•&nbsp; DOCUMENTO CONFIDENCIAL &nbsp;•&nbsp; USO INTERNO</div>
    <div>TOTAL: " & Text(_totalRegistros) & " REGISTRO(S) &nbsp;•&nbsp; GERADO EM " & Text(
        Now(),
        "[$-pt-BR]dd/mm/yyyy HH:mm"
    ) & "</div>
</div>"
)

