Rules.InvariantScript:
If(
    varColunaOrdenacao = "ID",
    Set(
        varDirecaoOrdenacao,
        If(varDirecaoOrdenacao = SortOrder.Ascending, SortOrder.Descending, SortOrder.Ascending)
    ),
    // troca de coluna: define ID e começa descendente
    Set(varColunaOrdenacao, "ID"),
