)

ControlPropertyState.AutoRuleBindingString:
If(
    varColunaOrdenacao = "ID",
    Set(
        varDirecaoOrdenacao,
        If(varDirecaoOrdenacao = SortOrder.Ascending, SortOrder.Descending, SortOrder.Ascending)
    ),
    // troca de coluna: define ID e começa descendente
    Set(varColunaOrdenacao, "ID"),
    Set(varDirecaoOrdenacao, SortOrder.Descending)
)

If(
    ocoNaero_aeroporto.Selected.Value = "TODOS OS AEROPORTOS",
    // --- Caso TODOS OS AEROPORTOS ---
    SortByColumns(
        Filter(
            tb_descumprimentoAIS,
            (IsBlank(ocoNaero_data_inicio.SelectedDate) || data >= ocoNaero_data_inicio.SelectedDate) && (IsBlank(ocoNaero_data_fim.SelectedDate) || data < DateAdd(
                ocoNaero_data_fim.SelectedDate,
                1,
                TimeUnit.Days
            ))
        ),
        "ID",
        SortOrder.Descending
    ),
    // --- Caso aeroporto específico ---
    SortByColumns(
        Filter(
            tb_descumprimentoAIS,
            aeroporto = ocoNaero_aeroporto.Selected.Value && (IsBlank(ocoNaero_data_inicio.SelectedDate) || data >= ocoNaero_data_inicio.SelectedDate) && (IsBlank(ocoNaero_data_fim.SelectedDate) || data < DateAdd(
                ocoNaero_data_fim.SelectedDate,
                1,
                TimeUnit.Days
            ))
        ),
        "ID",
        SortOrder.Descending
    )
)

