With(
    {
        statusSelecionado: OcoNaero_status_1.Selected.Value,
        objStatus: OcoNaero_status_1.Selected,
        ehAprovacao: OcoNaero_status_1.Selected.Value = "Aprovado - Aeroporto" || OcoNaero_status_1.Selected.Value = "Aprovado - Sede",
        ehRecusa: OcoNaero_status_1.Selected.Value = "Recusado - Aeroporto" || OcoNaero_status_1.Selected.Value = "Recusado - Sede"
    },
    With(
        {
            descricao: If(
                ehAprovacao,
                // ── Aprovação: captura edições relevantes ──────────
                With(
                    {
                        descEditada: If(
                            var_dados_ocoNaero.descricao_aeroporto <> DataCardValue16.Value,
                            "<b>Descrição <i>(editada):</i></b> " & Upper(DataCardValue16.Value),
                            ""
                        ),
                        acaoEditada: If(
                            var_dados_ocoNaero.acao_executada <> DataCardValue17.Value,
                            "<b>Ação <i>(editada):</i></b> " & Upper(DataCardValue17.Value),
                            ""
                        )
                    },
                    descEditada &
                    If(
                        descEditada <> "" && acaoEditada <> "",
                        "<br>",
                        ""
                    ) &
                    acaoEditada
                ),
                // ── Recusa / outros: usa motivo da recusa ──────────
                Upper(DataCardValueMotivoRecusa.Value)
            )
        },
        // ─── Validações (early return) ────────────────────────────
        If(
            IsBlank(statusSelecionado),
            Notify(
                "Selecione um status antes de continuar.",
                NotificationType.Error
            );
            UpdateContext({var_visibleProcessando: false}),

            ehRecusa && IsBlank(DataCardValueMotivoRecusa.Value),
            Notify(
                "O campo Motivo da Recusa é obrigatório para este status.",
                NotificationType.Error
            );
            UpdateContext({var_visibleProcessando: false}),

            // ─── Validações OK → inicia gravação ─────────────────
            With(
                {
                    registroDesdobramento: Patch(
                        tb_desdobramentos_ocorrencias_nao_aeronauticas,
                        Defaults(tb_desdobramentos_ocorrencias_nao_aeronauticas),
