                    // ❌ Patch 1 FALHOU
                    Notify(
                        $"Erro ao salvar o desdobramento: {FirstError.Message}",
                        NotificationType.Error,
                        10000
                    );
                    UpdateContext({var_visibleProcessando: false}),

                    // ✅ Patch 1 OK → tenta Patch 2 (capturado em With)
                    With(
                        {
                            registroAtualizado: Patch(
                                tb_relatorio_ocorrencias_nao_aeronauticas,
                                LookUp(
                                    tb_relatorio_ocorrencias_nao_aeronauticas,
                                    ID = var_dados_ocoNaero.ID
                                ),
                                {status: objStatus.Value}
                            )
                        },
                        IfError(
                            registroAtualizado,
                            // ❌ Patch 2 FALHOU → rollback Patch 1
                            Remove(
                                tb_desdobramentos_ocorrencias_nao_aeronauticas,
                                registroDesdobramento
                            );
                            Notify(
                                $"Falha ao atualizar a ocorrência. Desdobramento revertido. Detalhe: {FirstError.Message}",
                                NotificationType.Error,
                                10000
                            );
                            UpdateContext({var_visibleProcessando: false}),

                            // ✅ Patch 2 OK → sucesso total
                            Notify(
                                "Registro salvo com sucesso!",
                                NotificationType.Success
                            );
                            Reset(OcoNaero_status_1);
                            Reset(DataCardValueMotivoRecusa);
                            Refresh(tb_relatorio_ocorrencias_nao_aeronauticas);
                            Refresh(tb_desdobramentos_ocorrencias_nao_aeronauticas);
                            // ← recebe o RETORNO do Patch (último estado, sem cache)
                            UpdateContext({var_dados_ocoNaero: registroAtualizado});
                            UpdateContext({var_visibleProcessando: false})
                        )
                    )
                )
            )
        )
    )
)

